TLM.f("Tempora/PentEpi3-1",{"officium":"Feria II infra Hebdomadam III quæ superfuit post Epiphaniam","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/PentEpi3-0","from":{"Introitus":"Tempora/PentEpi3-0","Oratio":"Tempora/PentEpi3-0","Lectio":"Tempora/PentEpi3-0","Graduale":"Tempora/PentEpi3-0","Evangelium":"Tempora/PentEpi3-0","Offertorium":"Tempora/PentEpi3-0","Secreta":"Tempora/PentEpi3-0","Communio":"Tempora/PentEpi3-0","Postcommunio":"Tempora/PentEpi3-0"},"sections":{"Introitus":[{"k":"ref","la":"Jer 29:11; 29:12; 29:14"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."},{"k":"ref","la":"Ps 84:2"},{"k":"text","la":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, infirmitatem nostram propítius réspice: atque, ad protegéndum nos, déxteram tuæ majestátis exténde."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános."},{"k":"ref","la":"Rom 12:16-21"},{"k":"text","la":"Fratres: Nolíte esse prudéntes apud vosmetípsos: nulli malum pro malo reddéntes: providéntes bona non tantum coram Deo, sed étiam coram ómnibus homínibus. Si fíeri potest, quod ex vobis est, cum ómnibus homínibus pacem habéntes: Non vosmetípsos defendéntes, caríssimi, sed date locum iræ. Scriptum est enim: Mihi vindícta: ego retríbuam, dicit Dóminus. Sed si esuríerit inimícus tuus, ciba illum: si sitit, potum da illi: hoc enim fáciens, carbónes ignis cóngeres super caput ejus. Noli vinci a malo, sed vince in bono malum."}],"Graduale":[{"k":"ref","la":"Ps 43:8-9"},{"k":"text","la":"Liberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti."},{"k":"text","la":"In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 8:1-13"},{"k":"text","la":"In illo témpore: Cum descendísset Jesus de monte, secútæ sunt eum turbæ multæ: et ecce, leprósus véniens adorábat eum, dicens: Dómine, si vis, potes me mundáre. Et exténdens Jesus manum, tétigit eum, dicens: Volo. Mundáre. Et conféstim mundáta est lepra ejus. Et ait illi Jesus: Vide, némini díxeris: sed vade, osténde te sacerdóti, et offer munus, quod præcépit Móyses, in testimónium illis. Cum autem introísset Caphárnaum, accéssit ad eum centúrio, rogans eum et dicens: Dómine, puer meus jacet in domo paralýticus, et male torquetur. Et ait illi Jesus: Ego véniam, et curábo eum. Et respóndens centúrio, ait: Dómine, non sum dignus, ut intres sub tectum meum: sed tantum dic verbo, et sanábitur puer meus. Nam et ego homo sum sub potestáte constitútus, habens sub me mílites, et dico huic: Vade, et vadit; et alii: Veni, et venit; et servo meo: Fac hoc, et facit. Audiens autem Jesus, mirátus est, et sequéntibus se dixit: Amen, dico vobis, non inveni tantam fidem in Israël. Dico autem vobis, quod multi ab Oriénte et Occidénte vénient, et recúmbent cum Abraham et Isaac et Jacob in regno cœlórum: fílii autem regni ejiciéntur in ténebras exterióres: ibi erit fletus et stridor déntium. Et dixit Jesus centurióni: Vade et, sicut credidísti, fiat tibi. Et sanátus est puer in illa hora."}],"Offertorium":[{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine."}],"Secreta":[{"k":"text","la":"Hæc hóstia, Dómine, quǽsumus, emúndet nostra delícta: et, ad sacrifícium celebrándum, subditórum tibi córpora mentésque sanctíficet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Marc 11:24"},{"k":"text","la":"Amen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis."}],"Postcommunio":[{"k":"text","la":"Quos tantis, Dómine, largíris uti mystériis: quǽsumus; ut efféctibus nos eórum veráciter aptáre dignéris."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ba591f95b6d2e86d":{"t":"Jer 29, 11-12.14, Ps 84, 2\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva. (Ps 84, 2) Blagoslovio si, Gospodine, svoju zemlju, na dobro si okrenuo Jakovljevu sudbinu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva."},"e2ae07777a51ab3b":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, milostivo pogledaj na našu slabost i pruži desnicu svojega veličanstva da nas zaštitiš.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"b318a1049d40aad5":{"t":"Rim 12, 16-21\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: Ne smatrajte sami sebe mudrima, ne vraćajte nikome zla za zlo, nastojte oko dobra ne samo pred Bogom nego i pred svim ljudima. Ako je moguće i koliko je do vas, budite u miru sa svima. Ne osvećujte se, predragi, nego prepustite to Božjoj srdžbi, kao što je pisano: »Moja je osveta, ja ću uzvratiti«, kaže Gospodin. Naprotiv, ako je tvoj neprijatelj gladan, nahrani ga, ako je žedan napoji ga. Čineći tako skupit ćeš žeravicu na njegovu glavu. Ne daj se nadvladati od zla, nego zlo svladaj dobrom."},"a8b02c4b81c26ed7":{"t":"Ps 43, 8-9\nSpasio si nas, Gospodine, od naših protivnika i smeo si naše mrzitelje. U Bogu je naša slava u svako doba, i uvijek hvalimo ime tvoje.\n\nPs 129, 1-2\n<i>Aleluja</i>, <i>aleluja</i>.\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. <i>Aleluja</i>."},"4755f434b0add207":{"t":"Mt 8, 1-13\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: kad je Isus sišao s gore, išlo je za njim mnogo naroda. I gle, pristupi gubavac koji mu se pokloni i reče: Gospodine, ako hoćeš, možeš me očistiti. Isus pruži ruku, dotakne ga i reče Hoću. Budi čist. I odmah se očisti od svoje gube. Tada mu Isus reče: Pazi, ne kazuj nikome, nego pođi, pokaži se svećeniku i prinesi dar njima za svjedočanstvo, kako je naredio Mojsije. Kad je Isus ušao u Kafarnaum pristupi k njemu stotnik, zamoli ga i reče: Gospodine, moj sluga leži kod kuće uzet i teško se muči. Isus mu reče: Ja ću doći i izliječit ću ga. A stotnik odgovori: Gospodine, nisam dostojan da uđeš pod krov moj, nego samo reci riječ i ozdravit će moj sluga. I ja sam čovjek pod vlašću i imam pod sobom vojnike, pa kažem jednomu: Idi, – i on ide, i drugome: Dođi, – i on dođe, a svojem sluzi: Učini to, – i on učini. Kad je Isus to čuo, zadivi se i reče pratiocima: Zaista vam kažem u Izraelu nisam našao tolike vjere. Kažem vam da će doći mnogi s istoka i sa zapada i sjest će s Abrahamom, Izakom i Jakovom za stol u nebeskom kraljevstvu, a sinovi će kraljevstva biti izbačeni napolje u tamu, gdje će biti plač i škripa zubi. A stotniku reče: Idi i neka ti bude kako si vjerovao. I u taj čas ozdravi sluga."},"8a9f1217916db598":{"t":"Ps 129, 1-2\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. Iz dubine vapijem k tebi, Gospodine."},"fbb53f48d9c24f02":{"t":"Molimo, Gospodine, da ovaj žrtveni dar izbriše naša zlodjela te da dušu i tijelo tvojih podložnika posveti za svetkovanje žrtve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"2a2aa3c192299041":{"t":"Mk 11, 24\nZaista vam kažem: Što god moleći zaištete, vjerujte da ćete dobiti, i bit će vam."},"f2d0892ba07a1752":{"t":"<i>Pomolimo se</i>.\nNama, Gospodine, kojima daješ tolika otajstva, udostoj se dati i to da doista dostojno primamo njihove učinke.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
